    68  DEFINE_NULL_INSTANCE (hb_face_t) =
    69  {
    70    HB_OBJECT_HEADER_STATIC,
   157  static hb_blob_t *
   158  _hb_face_for_data_reference_table (hb_face_t *face HB_UNUSED, hb_tag_t tag, void *user_data)
   159  {
   160    hb_face_for_data_closure_t *data = (hb_face_for_data_closure_t *) user_data;
   161
   162    if (tag == HB_TAG_NONE)
   163      return hb_blob_reference (data->blob);
   164
   165    const OT::OpenTypeFontFile &ot_file = *data->blob->as<OT::OpenTypeFontFile> ();
   166    unsigned int base_offset;
   167    const OT::OpenTypeFontFace &ot_face = ot_file.get_face (data->index, &base_offset);
   168
   169    const OT::OpenTypeTable &table = ot_face.get_table_by_tag (tag);
   170
   171    hb_blob_t *blob = hb_blob_create_sub_blob (data->blob, base_offset + table.offset, table.length);
   172
   173    return blob;
   174  }
