   176  /**
   177   * hb_face_create: (Xconstructor)
   178   * @blob:
   179   * @index:
   180   *
   181   *
   182   *
   183   * Return value: (transfer full):
   184   *
   185   * Since: 0.9.2
   186   **/
   187  hb_face_t *
   188  hb_face_create (hb_blob_t    *blob,
   189                  unsigned int  index)
   190  {
   191    hb_face_t *face;
   192
   193    if (unlikely (!blob))
   194      blob = hb_blob_get_empty ();
   195
   196    hb_face_for_data_closure_t *closure = _hb_face_for_data_closure_create (hb_sanitize_context_t ().sanitize_blob<OT::OpenTypeFontFile> (hb_blob_reference (blob)), index);
   197
   198    if (unlikely (!closure))
   199      return hb_face_get_empty ();
   200
   201    face = hb_face_create_for_tables (_hb_face_for_data_reference_table,
   202                                      closure,
   203                                      _hb_face_for_data_closure_destroy);
   204
   205    face->index = index;
   206
   207    return face;
   208  }
